div.script:
        // ============ EDIT THIS ONE LINE ============
        var API_BASE = "https://YOUR-NGROK-ID.ngrok-free.app";
        // ============================================

        var html = "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chat</title>
<style>
  :root {
    --bg: #212121;
    --surface: #2f2f2f;
    --surface-hover: #3a3a3a;
    --text: #ececec;
    --text-dim: #b4b4b4;
    --blue: #0b6bcb;
    --input-bg: #2f2f2f;
    --border: #424242;
    --user-bubble: #2f2f2f;
    --radius: 24px;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    height: 100%; width: 100%;
    background: var(--bg); color: var(--text);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 16px; overflow: hidden;
  }
  #app {
    display: flex; flex-direction: column;
    height: 100%; width: 100%;
  }

  /* thin top bar — only brand + new chat + user */
  .topbar {
    height: 52px; flex-shrink: 0;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 16px;
    border-bottom: 1px solid #2a2a2a;
  }
  .brand { font-weight: 600; font-size: 16px; letter-spacing: -0.01em; }
  .topbar-right { display: flex; align-items: center; gap: 8px; }
  .icon-btn {
    width: 36px; height: 36px; border-radius: 8px; border: none;
    background: transparent; color: var(--text-dim); cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 18px;
  }
  .icon-btn:hover { background: var(--surface-hover); color: var(--text); }
  .user-chip {
    display: flex; align-items: center; gap: 8px;
    padding: 4px 10px 4px 4px; border-radius: 999px;
    background: transparent; border: 1px solid var(--border);
    cursor: pointer; color: var(--text); font-size: 13px;
  }
  .user-chip:hover { background: var(--surface-hover); }
  .avatar {
    width: 28px; height: 28px; border-radius: 50%;
    background: #555; display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 600; color: #fff; flex-shrink: 0;
  }
  .avatar.has-user { background: var(--blue); }

  /* chat area */
  #chat-area {
    flex: 1; overflow-y: auto;
    display: flex; flex-direction: column; align-items: center;
    padding: 0 16px 24px;
  }
  .chat-inner {
    width: 100%; max-width: 768px;
    display: flex; flex-direction: column; gap: 24px;
    padding-top: 24px; padding-bottom: 12px;
  }
  #empty {
    flex: 1; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 12px;
    width: 100%; max-width: 720px; margin: 0 auto; padding: 0 16px;
  }
  .empty-title {
    font-size: 28px; font-weight: 600; letter-spacing: -0.02em; text-align: center;
  }
  .empty-sub { font-size: 14px; color: var(--text-dim); text-align: center; }

  .msg { display: flex; gap: 16px; width: 100%; }
  .msg.user { flex-direction: row-reverse; }
  .msg-avatar {
    width: 32px; height: 32px; border-radius: 50%; flex-shrink: 0;
    display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 600; color: #fff;
  }
  .msg.assistant .msg-avatar { background: #10a37f; }
  .msg.user .msg-avatar { background: var(--blue); }
  .msg-body {
    max-width: calc(100% - 48px); line-height: 1.6; font-size: 15.5px;
    white-space: pre-wrap; word-break: break-word;
  }
  .msg.user .msg-body {
    background: var(--user-bubble); padding: 10px 16px; border-radius: 18px;
  }

  /* input dock */
  #dock {
    width: 100%; max-width: 768px; margin: 0 auto;
    padding: 0 16px 20px; flex-shrink: 0;
  }
  .input-shell {
    background: var(--input-bg); border-radius: var(--radius);
    display: flex; align-items: flex-end;
    padding: 10px 12px 10px 14px; gap: 8px;
    box-shadow: 0 0 0 1px rgba(255,255,255,0.05);
  }
  .input-shell:focus-within { box-shadow: 0 0 0 1px rgba(255,255,255,0.12); }
  #prompt {
    flex: 1; background: transparent; border: none; outline: none;
    color: var(--text); font-size: 15.5px; line-height: 1.5;
    resize: none; max-height: 200px; min-height: 24px;
    padding: 4px 0; font-family: inherit;
  }
  #prompt::placeholder { color: #8e8e8e; }
  .send-btn {
    width: 36px; height: 36px; border-radius: 50%; border: none;
    background: #fff; color: #000; cursor: pointer;
    display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  }
  .send-btn:disabled { opacity: .35; cursor: default; }
  .send-btn svg { width: 18px; height: 18px; }
  .disclaimer {
    text-align: center; font-size: 12px; color: #8e8e8e; margin-top: 10px;
  }

  .cursor {
    display: inline-block; width: 7px; height: 16px; background: var(--text);
    margin-left: 2px; vertical-align: text-bottom;
    animation: blink 1s step-end infinite;
  }
  @keyframes blink { 50% { opacity: 0; } }

  /* user modal */
  .modal-bg {
    position: fixed; inset: 0; background: rgba(0,0,0,.55);
    display: none; align-items: center; justify-content: center; z-index: 50;
  }
  .modal-bg.open { display: flex; }
  .modal {
    background: #2a2a2a; border-radius: 16px; padding: 24px;
    width: min(360px, 92vw); border: 1px solid #3a3a3a;
  }
  .modal h3 { font-size: 18px; margin-bottom: 6px; }
  .modal p { font-size: 13px; color: var(--text-dim); margin-bottom: 16px; }
  .modal input {
    width: 100%; padding: 10px 12px; border-radius: 10px;
    border: 1px solid var(--border); background: #1e1e1e; color: var(--text);
    font-size: 15px; outline: none; margin-bottom: 16px;
  }
  .modal input:focus { border-color: #666; }
  .modal-actions { display: flex; gap: 8px; justify-content: flex-end; }
  .btn {
    padding: 8px 16px; border-radius: 10px; border: none;
    font-size: 14px; cursor: pointer;
  }
  .btn-ghost { background: transparent; color: var(--text-dim); }
  .btn-ghost:hover { background: var(--surface-hover); color: var(--text); }
  .btn-primary { background: #fff; color: #000; font-weight: 500; }
  .btn-primary:hover { opacity: .9; }

  ::-webkit-scrollbar { width: 8px; }
  ::-webkit-scrollbar-thumb { background: #444; border-radius: 4px; }
</style>
</head>
<body>
<div id="app">
  <div class="topbar">
    <span class="brand">Chat</span>
    <div class="topbar-right">
      <button class="icon-btn" id="btn-new" title="New chat">＋</button>
      <button class="user-chip" id="btn-user" title="Set username">
        <div class="avatar" id="avatar">?</div>
        <span id="username-label">User</span>
      </button>
    </div>
  </div>

  <div id="chat-area">
    <div id="empty">
      <div class="empty-title">What's on the agenda today?</div>
      <div class="empty-sub">Conversations save in this browser.</div>
    </div>
    <div class="chat-inner" id="messages" style="display:none"></div>
  </div>

  <div id="dock">
    <div class="input-shell">
      <textarea id="prompt" rows="1" placeholder="Ask anything"></textarea>
      <button class="send-btn" id="btn-send" disabled title="Send">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
      </button>
    </div>
    <div class="disclaimer">Local AI · messages stay on this device</div>
  </div>
</div>

<!-- username modal -->
<div class="modal-bg" id="user-modal">
  <div class="modal">
    <h3>Choose a name</h3>
    <p>Shown next to your messages. Stored only in this browser.</p>
    <input id="name-input" type="text" maxlength="24" placeholder="User" autocomplete="off">
    <div class="modal-actions">
      <button class="btn btn-ghost" id="btn-cancel">Cancel</button>
      <button class="btn btn-primary" id="btn-save-name">Save</button>
    </div>
  </div>
</div>

<script>
/* =========================================================
   CONFIG — change to your ngrok URL
   ========================================================= */
const API_BASE = (function () {
  const p = new URLSearchParams(location.search);
  if (p.get("api")) return p.get("api").replace(/\/$/, "");
  return window.API_BASE || "http://127.0.0.1:8000";
})();

const LS_USER = "mini_chat_user";
const LS_CONVOS = "mini_chat_convos";
const LS_ACTIVE = "mini_chat_active";

const $ = (s, el = document) => el.querySelector(s);
const messagesEl = $("#messages");
const emptyEl = $("#empty");
const promptEl = $("#prompt");
const sendBtn = $("#btn-send");
const chatArea = $("#chat-area");
const avatarEl = $("#avatar");
const nameLabel = $("#username-label");
const modal = $("#user-modal");
const nameInput = $("#name-input");

let username = localStorage.getItem(LS_USER) || "";
let sessionId = localStorage.getItem(LS_ACTIVE) || null;
let convos = loadConvos();
let busy = false;

function loadConvos() {
  try { return JSON.parse(localStorage.getItem(LS_CONVOS) || "{}"); }
  catch { return {}; }
}
function saveConvos() {
  localStorage.setItem(LS_CONVOS, JSON.stringify(convos));
}
function setActive(id) {
  sessionId = id;
  if (id) localStorage.setItem(LS_ACTIVE, id);
  else localStorage.removeItem(LS_ACTIVE);
}

function applyUser() {
  if (username) {
    nameLabel.textContent = username;
    avatarEl.textContent = username.slice(0, 2).toUpperCase();
    avatarEl.classList.add("has-user");
  } else {
    nameLabel.textContent = "User";
    avatarEl.textContent = "?";
    avatarEl.classList.remove("has-user");
  }
}
applyUser();

function autoGrow() {
  promptEl.style.height = "auto";
  promptEl.style.height = Math.min(promptEl.scrollHeight, 200) + "px";
  sendBtn.disabled = !promptEl.value.trim() || busy;
}
promptEl.addEventListener("input", autoGrow);
promptEl.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey) {
    e.preventDefault();
    if (!sendBtn.disabled) send();
  }
});

$("#btn-send").addEventListener("click", send);
$("#btn-new").addEventListener("click", newChat);
$("#btn-user").addEventListener("click", () => {
  nameInput.value = username || "";
  modal.classList.add("open");
  nameInput.focus();
  nameInput.select();
});
$("#btn-cancel").addEventListener("click", () => modal.classList.remove("open"));
$("#btn-save-name").addEventListener("click", saveName);
nameInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") saveName();
  if (e.key === "Escape") modal.classList.remove("open");
});
modal.addEventListener("click", (e) => {
  if (e.target === modal) modal.classList.remove("open");
});

function saveName() {
  const v = nameInput.value.trim().slice(0, 24);
  username = v || "";
  if (username) localStorage.setItem(LS_USER, username);
  else localStorage.removeItem(LS_USER);
  applyUser();
  modal.classList.remove("open");
  // refresh user avatars already on screen
  document.querySelectorAll(".msg.user .msg-avatar").forEach((el) => {
    el.textContent = username ? username.slice(0, 2).toUpperCase() : "U";
  });
}

function showChat() {
  emptyEl.style.display = "none";
  messagesEl.style.display = "flex";
}

function newChat() {
  setActive(null);
  messagesEl.innerHTML = "";
  emptyEl.style.display = "flex";
  messagesEl.style.display = "none";
  promptEl.value = "";
  autoGrow();
  promptEl.focus();
}

function addMessage(role, text) {
  showChat();
  const row = document.createElement("div");
  row.className = `msg ${role}`;
  const av = document.createElement("div");
  av.className = "msg-avatar";
  if (role === "user") {
    av.style.background = "var(--blue)";
    av.textContent = username ? username.slice(0, 2).toUpperCase() : "U";
  } else {
    av.style.background = "#10a37f";
    av.textContent = "AI";
  }
  const body = document.createElement("div");
  body.className = "msg-body";
  body.textContent = text;
  row.appendChild(av);
  row.appendChild(body);
  messagesEl.appendChild(row);
  chatArea.scrollTop = chatArea.scrollHeight;
  return body;
}

function persistMessage(role, content) {
  if (!sessionId) {
    sessionId = crypto.randomUUID();
    setActive(sessionId);
    convos[sessionId] = { id: sessionId, title: content.slice(0, 40), messages: [], ts: Date.now() };
  }
  if (!convos[sessionId]) {
    convos[sessionId] = { id: sessionId, title: content.slice(0, 40), messages: [], ts: Date.now() };
  }
  convos[sessionId].messages.push({ role, content });
  convos[sessionId].ts = Date.now();
  if (role === "user" && convos[sessionId].messages.length === 1) {
    convos[sessionId].title = content.slice(0, 48);
  }
  saveConvos();
}

function restoreActive() {
  if (!sessionId || !convos[sessionId]) return;
  const msgs = convos[sessionId].messages || [];
  if (!msgs.length) return;
  messagesEl.innerHTML = "";
  for (const m of msgs) addMessage(m.role, m.content);
  showChat();
}
restoreActive();

async function send() {
  const text = promptEl.value.trim();
  if (!text || busy) return;
  busy = true;
  sendBtn.disabled = true;

  addMessage("user", text);
  persistMessage("user", text);
  promptEl.value = "";
  autoGrow();

  const body = addMessage("assistant", "");
  body.innerHTML = '<span class="cursor"></span>';

  try {
    const res = await fetch(`${API_BASE}/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message: text, session_id: sessionId, stream: true })
    });
    if (!res.ok) throw new Error("HTTP " + res.status);

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let full = "";
    let buf = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const parts = buf.split("\n\n");
      buf = parts.pop();
      for (const part of parts) {
        if (!part.startsWith("data: ")) continue;
        const data = part.slice(6);
        if (data === "[DONE]") continue;
        try {
          const j = JSON.parse(data);
          if (j.session_id) {
            sessionId = j.session_id;
            setActive(sessionId);
            continue;
          }
        } catch (_) {}
        full += data;
        body.innerHTML = full + '<span class="cursor"></span>';
        chatArea.scrollTop = chatArea.scrollHeight;
      }
    }
    body.textContent = full || "(no response)";
    persistMessage("assistant", body.textContent);
  } catch (err) {
    body.textContent = "Connection failed — is the server + ngrok running?\n" + err.message;
  } finally {
    busy = false;
    autoGrow();
    promptEl.focus();
  }
}

promptEl.focus();
</script>
</body>
</html>
";
        // inject API override into the embedded page
        html = html.replace(
          'return window.API_BASE || "http://127.0.0.1:8000";',
          'return window.API_BASE || "' + API_BASE + '";'
        );

        var frame = document.getElementById("frame");
        var doc = frame.contentDocument || frame.contentWindow.document;
        doc.open();
        doc.write(html);
        doc.close();
